from funcy import cache, memoize, SkipMemoization

# Test cache with skip exception
@cache(timeout=60)
def cached_func(x):
    if x == 999:
        raise SkipMemoization("bypass")
    return x * 2

print(f"cached_func(5): {cached_func(5)}")
print(f"cached_func(999): {cached_func(999)}")
print()

# Test memoize with skip exception  
@memoize
def memoized_func(x):
    if x == 999:
        raise SkipMemoization("bypass")
    return x * 2

print(f"memoized_func(5): {memoized_func(5)}")
print(f"memoized_func(999): {memoized_func(999)}")
EOF
